const deliveryTermsVersion='demo-delivery-1';
const facilityCityState=()=>lifeData?.preferences?.facility_state?.[selectedFarmCity()]||{};
const deliveryLocationOpen=()=>facilityCityState().delivery?.version===deliveryTermsVersion;
let facilityUserLoaded=null;
function decorateFacilitySlots(){if(!account||location.hash!=='#home')return;if(facilityUserLoaded!==account.id){facilityUserLoaded=account.id;lifeData=null;queueMicrotask(loadLife)}const buildings=document.querySelectorAll('.farm-map-objects .farm-building');const storage=!!hasStorage(),delivery=deliveryLocationOpen();[[2,storage,'Склад','openStorageSlot'],[3,delivery,'Доставка','openDeliverySlot']].forEach(([i,active,title,action])=>{const el=buildings[i];if(!el)return;el.onclick=e=>{e.preventDefault();window[action]()};if(!active){el.classList.add('facility-empty');el.innerHTML=`<span class="facility-empty-land" aria-hidden="true">＋</span><b>${title}</b><small>${!lifeData?'Проверяем статус…':i===2?(facilityCityState().storage_request?'Строительство · заявка отправлена':'Арендовать или построить'):'Открыть локацию'}</small>`;el.title=title+' · свободный слот';}})}
farmViews.add(decorateFacilitySlots);
async function ensureFacilities(){if(!account){profile();return false}if(!lifeData){await loadLife();if(!lifeData){toast('Не удалось проверить локации. Попробуйте ещё раз.');return false}}return true}
async function openStorageSlot(){if(!await ensureFacilities())return;if(hasStorage()){location.hash='warehouse';return}modalForm('🏗️ Здесь будет ваш склад',`<p>Выберите, как подключить хранение урожая.</p><button type="button" class="btn" onclick="subscribeLife('storage')">Арендовать · 400 демо-₽ / месяц</button><button type="button" class="btn light" onclick="requestStorageBuild()">${facilityCityState().storage_request?'Посмотреть заявку на строительство':'Построить свой склад'}</button><p>Аренда включает кладовую и холодильник в рамках демоподписки. Строительство требует отдельной сметы и подтверждения фермы.</p>`,()=>{})}
function requestStorageBuild(){const request=facilityCityState().storage_request;if(request){modalForm('🏗️ Заявка на склад отправлена','<p>Управляющий должен согласовать место, стоимость и сроки. Здание появится после подтверждённого подключения хранения.</p><button type="button" class="btn" onclick="modal.close()">Понятно</button>',()=>{});return}const city=selectedFarmCity();formAsync('🏗️ Построить склад',`<p>Город: ${esc(neighborCity(city)?.name||'')}. Это заявка на расчёт — средства сейчас не списываются.</p><label>Пожелания<textarea name="notes" maxlength="1000" placeholder="Кладовая, холодильник, удобное размещение"></textarea></label><button class="btn">Запросить смету и сроки</button>`,async f=>{await lifeAction('facility',{city,kind:'storage_request',notes:f.get('notes')});toast('Заявка на строительство склада отправлена управляющему')})}
async function openDeliverySlot(){if(!await ensureFacilities())return;if(deliveryLocationOpen()){location.hash='delivery';return}const city=selectedFarmCity();formAsync('🚚 Открыть локацию доставки',`<h3>Демоусловия · версия 1</h3><p>Это учебные условия для тестирования сервиса. Подпись ниже сохраняет ознакомление внутри демоверсии и не оформляет реальный договор перевозки.</p><ol><li>Вы собираете корзину из доступного урожая одного города.</li><li>Адрес, упаковку, стоимость и время доставки согласуем отдельно перед оплатой.</li><li>Открытие локации бесплатно и само по себе ничего не отправляет.</li><li>В деморежиме реальный курьер не вызывается, реальные деньги не списываются.</li><li>При получении можно отметить недостачу или повреждение и обратиться в поддержку.</li></ol><label>Игровой ник · демоподпись<input name="signature" required minlength="2" maxlength="60" value="${esc(account.name)}"></label><label class="delivery-consent"><input type="checkbox" name="accepted" required> Я прочитал демоусловия доставки</label><button class="btn">Подписать демоусловия и открыть</button>`,async f=>{await lifeAction('facility',{city,kind:'delivery',version:deliveryTermsVersion,accepted:f.get('accepted')==='on',signature:f.get('signature')});toast('Локация доставки открыта. Теперь можно собирать корзину')})}
const basketBeforeFacility=basketForm;basketForm=function(...args){if(!deliveryLocationOpen()){openDeliverySlot();return}return basketBeforeFacility(...args)};
modal.addEventListener('close',()=>{if(location.hash==='#home')requestAnimationFrame(()=>{if(!modal.open)render()})});
